public static int count(int[] arr, int x) {
    int count = 0;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] == x) {
            count++;
        }
    }
    return count;
}

public static boolean isSorted(int[] arr) {
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] < arr[i - 1]) {
            return false;
        }
    }
    return true;
}

exercise.mainCode:
int[] arr = { 3, 5, 3, 7, 3 };
int[] up = { 1, 2, 4, 7 };
int[] notUp = { 1, 5, 3 };
System.out.println("סעיף א: " + count(arr, 3) + " " + count(arr, 8));
System.out.println("סעיף ב: " + isSorted(up) + " " + isSorted(notUp));

